mod.web_layout.BackendLayouts.restricted {
  title = Restricted
  config.backend_layout {
    colCount = 2
    rowCount = 1
    rows.1.columns {
      1 {
        name = Main
        colPos = 0
        disallowedContentTypes = html
      }
      2 {
        name = Header only
        colPos = 1
        allowedContentTypes = header
      }
    }
  }
}
